package com.agacostays.billing.controller;import com.agacostays.billing.dto.response.*;import com.agacostays.billing.service.BillingService;import org.springframework.data.domain.Pageable;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/manager/hotel-branches") public class FinalBillController{private final BillingService s;public FinalBillController(BillingService s){this.s=s;}@GetMapping("/{branchId}/bills")public ResponseEntity<ApiResponse<PageResponse<FinalBillResponse>>> bills(@PathVariable Long branchId,Pageable p){return ResponseEntity.ok(ApiResponse.ok("Branch bills fetched",s.branchBills(branchId,p)));}}
